INSERT IGNORE INTO brgy_sop_steps (process, code, step_no, section, section_title, title, instructions, papers, checks, action, role_hint, sort_order, is_active) VALUES
  ('svp', 'svp1', '1', 'A', 'Pre-processing', 'Receive transaction details', 'The Sales Representative shall provide the project title, the approved budget, the requestor, the inspector and the complete item specifications / particulars. If complete details are already available, document preparation may proceed immediately. Otherwise, additional research and price validation shall be conducted before processing.', 'txn_form', 'Project title|Approved budget|Requestor|Inspector|Complete item specifications / particulars', 'details', 'Sales Representative', '10', '1'),
  ('svp', 'svp2', '2', 'B', 'Preparation of procurement documents', 'Prepare the required documents', 'The following documents shall be prepared: Purchase Request (PR), Purchase Order (PO), Inspection and Acceptance Report (IAR), Requisition and Issue Slip (RIS), Canvass, Abstract of Canvass, Disbursement Voucher (DV).', 'pr,po,iar,ris,canvass,abstract,dv', NULL, 'prepare', 'Documentation staff', '20', '1'),
  ('svp', 'svp3', '3', 'B', 'Preparation of procurement documents', 'Supplier canvassing', 'Three (3) supplier representatives shall complete and sign the canvass forms. For a complete canvass: three suppliers signed.', NULL, 'Three suppliers completed and signed the canvass forms', 'canvass', 'Documentation staff', '30', '1'),
  ('svp', 'svp4', '4', 'C', 'Billing and tax documents', 'Prepare billing documents', 'Prepare the Sales Invoice (SI), the Official Receipt (OR) and the BIR Form 2307 (3 copies). All copies of BIR Form 2307 must be signed by the proprietor. Signed copies are uploaded to the system. Special case (F): if payment has not yet been released, do NOT prepare the sales invoice, the official receipt and the BIR Form 2307; monitor the transaction until payment is available. Once payment is released, proceed with the preparation of the billing documents and continue the normal closing process.', 'si,or,form_2307', 'All copies of BIR Form 2307 signed by the proprietor', 'billing_docs', 'Billing staff', '40', '1'),
  ('svp', 'svp5', '5', 'D', 'Review and monitoring', 'Review documents', 'Conduct a thorough review to ensure accuracy, completeness, proper signatures and correct computations.', NULL, 'Accuracy|Completeness|Proper signatures|Correct computations', 'review', 'Reviewer', '50', '1'),
  ('svp', 'svp6', '6', 'D', 'Review and monitoring', 'File and monitor records', 'Retain copies of all essential documents for monitoring and future reference. Encode transaction details into the Monitoring System.', NULL, 'Copies of all essential documents retained|Transaction details encoded in the Monitoring System', 'monitor', 'Documentation staff', '60', '1'),
  ('svp', 'svp7', '7', 'E', 'Accounting and release', 'Forward documents', 'Forward all retained copies to the Accounting Department for final processing and closing.', NULL, NULL, 'forward', 'Documentation staff', '70', '1'),
  ('svp', 'svp8', '8', 'E', 'Accounting and release', 'Prepare transmittal', 'Prepare the transmittal documents for routing and tracking purposes.', 'transmittal', NULL, 'transmittal', 'Documentation staff', '80', '1'),
  ('svp', 'svp9', '9', 'E', 'Accounting and release', 'Release of documents', 'Documents may be delivered by the Sales Representative, or released directly to the Barangay Office for pick-up. The signed transmittal must always be returned for documentation and tracking.', NULL, NULL, 'release', 'Sales Representative / office', '90', '1'),
  ('bidding', 'bid1', '1', 'A', 'Receipt of bidding information', 'Receive bidding details', 'The Sales Representative shall provide the bidding form and complete project details.', 'bidding_form', 'Bidding form received|Complete project details', 'details', 'Sales Representative', '100', '1'),
  ('bidding', 'bid2', '2', 'A', 'Receipt of bidding information', 'Verify completeness', 'Ensure the following are finalized before processing: specifications, approved schedule, bid dates, submission requirements.', NULL, 'Specifications|Approved schedule|Bid dates|Submission requirements', 'checks', 'Bid officer', '110', '1'),
  ('bidding', 'bid3', '3', 'A', 'Receipt of bidding information', 'Posting on PhilGEPS', 'Post the bidding opportunity manually on PhilGEPS.', NULL, 'Posted on PhilGEPS', 'philgeps', 'Bid officer', '120', '1'),
  ('bidding', 'bid4', '4', 'B', 'Preparation of bidding documents', 'Prepare pre-bid documents', 'Prepare the Invitation to Bid (ITB), the Purchase Request (PR) and the Letter to COA; for the Cebu City offices also the Approved Budget for the Contract (ABC) and the Aboitiz requirements.', 'itb,pr,coa_letter,abc,aboitiz', NULL, 'prepare', 'Bid officer', '130', '1'),
  ('bidding', 'bid5', '5', 'C', 'Representative assignment', 'Assign authorized representative', 'Assign a representative to attend the pre-bid conference and the actual bidding. Prepare the Special Power of Attorney (SPA).', 'spa', 'Representative for the pre-bid conference|Representative for the actual bidding', 'representative', 'Proprietor', '140', '1'),
  ('bidding', 'bid6', '6', 'D', 'Eligibility and legal documents', 'Prepare legal documents', 'Prepare the following for notarization: Bid Securing Declaration, Omnibus Sworn Statement.', 'bsd,oss', 'Notarized', 'prepare', 'Bid officer', '150', '1'),
  ('bidding', 'bid7', '7', 'D', 'Eligibility and legal documents', 'Print eligibility documents', 'Retrieve and print from PhilGEPS: PhilGEPS registration, DTI/SEC registration, Mayor\'s permit, Certificate of Registration (COR), Tax clearance, Audited financial statements, Income tax return.', 'philgeps_reg,sec_dti,mayors_permit,cor,tax_clearance,afs,itr', NULL, 'prepare', 'Bid officer', '160', '1'),
  ('bidding', 'bid8', '8', 'E', 'Additional supporting documents', 'Prepare additional requirements', 'Statement of ongoing contracts, statement of similar contracts, supplier profile, letter of intent, technical specifications, production details, manpower schedule, warranty certificate.', 'slcc_ongoing,slcc_similar,supplier_profile,letter_intent,tech_specs,production,manpower,warranty_cert', NULL, 'prepare', 'Bid officer', '170', '1'),
  ('bidding', 'bid9', '9', 'F', 'Final review and submission', 'Organize and label documents', 'Arrange all documents properly and stamp them as \"Certified True Copy.\"', NULL, 'Documents arranged and labelled|Stamped \"Certified True Copy\"', 'checks', 'Bid officer', '180', '1'),
  ('bidding', 'bid10', '10', 'F', 'Final review and submission', 'Secure signatures', 'Present documents to the proprietor for signature.', NULL, NULL, 'signatures', 'Proprietor', '190', '1'),
  ('bidding', 'bid11', '11', 'F', 'Final review and submission', 'Final verification', 'Conduct final checking before submission. The bid is reviewed and approved for submission (two different people).', NULL, NULL, 'verify', 'Checker and approver', '200', '1');

