  ('bidding', 'pay3', '18', 'H', 'Payment process', 'Forward to accounting', 'Forward all retained copies to the Accounting Department for final processing and closing.', NULL, NULL, 'forward', 'Documentation staff', '270', '1'),
  ('bidding', 'pay4', '19', 'H', 'Payment process', 'Prepare transmittal', 'Prepare the transmittal documents for routing and tracking purposes.', 'transmittal', NULL, 'transmittal', 'Documentation staff', '280', '1'),
  ('bidding', 'pay5', '20', 'H', 'Payment process', 'Secure signature', 'Release the documents and secure the signature on the transmittal; the signed transmittal must always be returned.', NULL, NULL, 'release', 'Sales Representative / office', '290', '1'),
  ('bidding', 'pay6', '21', 'H', 'Payment process', 'File for record', 'File the transaction for record. The contract is closed out when it agrees with the ledger.', NULL, 'Filed for record', 'file', 'Documentation staff', '300', '1');

-- ---------------------------------------------------------------------
--  6. The proforma forms of the SOP (the existing templates keep their text; their format
--     starts from the defaults and is set on Proforma & Form Templates > Format)
-- ---------------------------------------------------------------------

SET @o = (SELECT COALESCE(MAX(sort_order), 0) FROM brgy_templates);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('txn_form', 'Transaction form', 'internal', 'internal', 'txn_form', 'Series-numbered transaction form of the SOP: tradename, type, barangay, cheque, amounts, requestor, inspector and purpose.', '<table class=\"fx fx-frame\" style=\"width:100%\"><tbody><tr><td style=\"padding:6px 10px\"><b>Series No:</b> <span class=\"fx-series\">{{txn.series}}</span></td></tr><tr><td class=\"fx-title\" style=\"text-align:center\">TRANSACTION FORM</td></tr><tr><td style=\"padding:8px 10px 10px\"><table class=\"fx-lines\" style=\"width:100%\"><tbody><tr><td class=\"lbl\">DATE:</td><td class=\"val\">{{txn.date}}</td></tr><tr><td class=\"lbl\">TRADENAME:</td><td class=\"val\">{{txn.tradename}}</td></tr><tr><td class=\"lbl\" style=\"vertical-align:middle\">TYPE:</td><td>{{txn.types}}</td></tr><tr><td class=\"lbl\">BARANGAY:</td><td class=\"val\">{{txn.barangay}}</td></tr><tr><td class=\"lbl\">CHEQUE NUMBER:</td><td class=\"val\">{{txn.cheque_no}}</td></tr><tr><td class=\"lbl\">GROSS AMOUNT:</td><td class=\"val\">{{txn.gross}}</td></tr><tr><td class=\"lbl\">WITHHOLDING TAX:</td><td class=\"val\">{{txn.wht}}</td></tr><tr><td class=\"lbl\">CHEQUE AMOUNT:</td><td class=\"val\">{{txn.cheque_amount}}</td></tr><tr data-section=\"profit\" title=\"Profit\"><td class=\"lbl\">PROFIT:</td><td class=\"val\">{{txn.profit}}</td></tr><tr><td class=\"lbl\">REQUESTOR:</td><td class=\"val\">{{txn.requestor}}</td></tr><tr><td class=\"lbl\">INSPECTOR:</td><td class=\"val\">{{txn.inspector}}</td></tr><tr><td class=\"lbl\">PURPOSE:</td><td class=\"val\">{{txn.purpose}}</td></tr></tbody></table></td></tr><tr><td style=\"padding:6px 10px\"><table class=\"fx-lines\" style=\"width:100%\"><tbody><tr><td class=\"lbl\" style=\"width:48%;text-align:left\">PREPARED / RECEIVED BY:</td><td class=\"val\">{{txn.prepared_by}}</td></tr></tbody></table></td></tr></tbody></table>', 'HalfLetter', 'portrait', '0', 'txn.series,txn.date,txn.barangay', '0', 'layout', '{\"margin_top\":7,\"margin_right\":7,\"margin_bottom\":7,\"margin_left\":7,\"line_height\":1.25,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":12.5}', '{\"paper\":\"HalfLetter\",\"orientation\":\"portrait\",\"width_mm\":\"\",\"height_mm\":\"\",\"offset_x\":0,\"offset_y\":0,\"font\":\"Arial\",\"font_size\":9.5,\"fields\":[{\"key\":\"txn.series\",\"text\":\"\",\"x\":42,\"y\":5,\"w\":50,\"size\":12,\"bold\":1,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.date\",\"text\":\"\",\"x\":43,\"y\":23,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.tradename\",\"text\":\"\",\"x\":43,\"y\":29.5,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.mark_purchases\",\"text\":\"\",\"x\":45.5,\"y\":49,\"w\":5,\"size\":10,\"bold\":1,\"align\":\"center\",\"upper\":0},{\"key\":\"txn.mark_construction\",\"text\":\"\",\"x\":45.5,\"y\":56,\"w\":5,\"size\":10,\"bold\":1,\"align\":\"center\",\"upper\":0},{\"key\":\"txn.barangay\",\"text\":\"\",\"x\":44,\"y\":64,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.cheque_no\",\"text\":\"\",\"x\":44,\"y\":69.5,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.gross\",\"text\":\"\",\"x\":44,\"y\":75,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.wht\",\"text\":\"\",\"x\":44,\"y\":80.5,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.cheque_amount\",\"text\":\"\",\"x\":44,\"y\":86,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.profit\",\"text\":\"\",\"x\":44,\"y\":100,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.requestor\",\"text\":\"\",\"x\":44,\"y\":122,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.inspector\",\"text\":\"\",\"x\":44,\"y\":127.5,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.purpose\",\"text\":\"\",\"x\":44,\"y\":133,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.prepared_by\",\"text\":\"\",\"x\":46,\"y\":148,\"w\":48,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0}],\"tables\":[]}', '1', '1', @o + 10);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('purchase_request', 'Purchase request (PR)', 'proforma', 'bid', 'pr', 'Purchase request of the barangay, with the estimated unit costs, prepared by the company for the requisitioner and the Punong Barangay.', '<table class=\"fx\" style=\"width:100%\"><tbody><tr><td colspan=\"2\" class=\"fx-title\" style=\"text-align:center;padding:12px\">PURCHASE REQUEST</td></tr><tr><td style=\"width:52%\">Barangay: <b>{{entity.short}}</b><br>City/Municipality: {{entity.city}}</td><td>P.R. No. {{pr.no}}<br>Date: {{pr.date}}</td></tr><tr><td colspan=\"2\" style=\"text-align:center;font-weight:bold\">REQUISITION</td></tr><tr><td colspan=\"2\" class=\"fx-slot\">{{pr.items}}</td></tr><tr><td colspan=\"2\"><b>Purpose : {{project.purpose}}</b></td></tr><tr><td style=\"height:140px;vertical-align:top\">Requested by:<div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{project.requestor}}</div><div class=\"sg-cap\">Signature over Printed Name<br>Requisitioner</div></div><div class=\"fx-dateline\">Date</div></td><td style=\"vertical-align:top\">Approved by:<div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{entity.head_name}}</div><div class=\"sg-cap\">Signature over Printed Name<br>Punong Barangay</div></div><div class=\"fx-dateline\">Date</div></td></tr></tbody></table>', 'A4', 'portrait', '0', 'entity.name,pr.no', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"blank_rows\":3}', NULL, '1', '1', @o + 20);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('purchase_order', 'Purchase order (PO)', 'proforma', 'contract', 'po', 'Purchase order of the barangay to the company: mode of procurement, items, penalty clause, conforme and appropriations.', '<table class=\"fx\" style=\"width:100%\"><tbody><tr><td colspan=\"2\" class=\"fx-title\" style=\"text-align:center;padding:12px\">PURCHASE ORDER</td></tr><tr><td colspan=\"2\" style=\"padding:0\"><table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:50%\">Barangay: <b>{{entity.short_upper}}</b><br>Tel. No. {{entity.phone}}</td><td>City/Municipality: {{entity.city}}<br>Province: {{entity.province}}</td></tr></tbody></table></td></tr><tr><td style=\"width:52%\">Supplier: <b>{{company.name}}</b></td><td>P.O. No. {{po.no}}</td></tr><tr><td style=\"vertical-align:top\">Address: {{company.address}}<br>TIN:   {{company.tin}}</td><td>Date {{po.date}}<br>Mode of procurement<div style=\"margin-top:6px\">{{po.modes}}</div></td></tr><tr><td colspan=\"2\">Gentlemen:<br><span style=\"padding-left:28px\">Please deliver to this office the following articles subject to the terms and conditions contained herein</span></td></tr><tr><td>Place of Delivery: {{po.place}}<br>Date of Delivery: {{po.delivery_date}}</td><td>Delivery term: {{po.delivery_term}}<br>Payment term: {{po.payment_term}}</td></tr><tr><td colspan=\"2\" class=\"fx-slot\">{{po.items}}</td></tr><tr><td colspan=\"2\"><b>**{{po.total_words}} Only. **</b></td></tr><tr><td colspan=\"2\" style=\"padding:6px 10px 14px\"><div data-section=\"penalty\" title=\"Penalty clause\">    In case of failure to make full delivery within the time specified above, a penalty of one-tenth (1/10) of one percent for everyday of delay shall be imposed.</div><table class=\"fx-plain\" style=\"width:100%;margin-top:14px\"><tbody><tr><td style=\"width:55%\"></td><td>Very truly yours,<div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{entity.head_name}}</div><div class=\"sg-cap\">Signature Over Printed Name<br>Punong Barangay</div></div></td></tr></tbody></table></td></tr><tr><td style=\"vertical-align:top;height:150px\">Conforme:<div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{company.name_upper}}</div><div class=\"sg-cap\">Signature over Printed Name<br>Supplier</div></div><div class=\"fx-dateline\">Date</div></td><td style=\"vertical-align:top\" data-section=\"appropriations\" title=\"Existence of available appropriations\">Existence of Available Appropriations of<div style=\"margin:6px 0\">( ____________________________________ )</div><div>(amount in words) ( figure )</div><div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{entity.appropriations_chair}}</div><div class=\"sg-cap\">Signature over Printed Name<br>Chairman, Committee on Appropriations</div></div><div>Date:</div></td></tr></tbody></table>', 'A4', 'portrait', '0', 'entity.name,po.no', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9,\"table_size\":9,\"title_size\":13,\"blank_rows\":2}', NULL, '1', '1', @o + 30);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('inspection_acceptance_report', 'Inspection and acceptance report (IAR)', 'proforma', 'delivery', 'iar', 'Inspection and acceptance report of the barangay for the items delivered: inspection by the inspector, acceptance by the custodian.', '<div class=\"fx-title\" style=\"text-align:center;margin-bottom:8px\">INSPECTION AND ACCEPTANCE REPORT</div><table class=\"fx\" style=\"width:100%\"><tbody><tr><td style=\"width:55%\">Entity Name: <b>{{entity.name}}</b></td><td>Fund Cluster: {{project.fund}}</td></tr><tr><td>Supplier: <b>{{company.name}}</b><br>PO No./Date: {{po.no}} / {{po.date}}<br>Requisitioning Office/Dept.: {{project.end_user}}<br>Responsibility Center Code:</td><td>IAR No.: {{iar.no}}<br>Date: {{iar.date}}<br>Invoice No.: {{iar.invoice_no}}<br>Date: {{iar.invoice_date}}</td></tr><tr><td colspan=\"2\" class=\"fx-slot\">{{iar.items}}</td></tr><tr><td style=\"text-align:center;font-weight:bold\">INSPECTION</td><td style=\"text-align:center;font-weight:bold\">ACCEPTANCE</td></tr><tr><td style=\"vertical-align:top;height:170px\">Date Inspected: {{iar.date}}<p style=\"margin-top:10px\"><span class=\"fx-chk is-on\"></span> Inspected, verified and found in order as to quantity and specifications</p><div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{project.inspector}}</div><div class=\"sg-cap\">Inspection Officer / Inspection Committee</div></div></td><td style=\"vertical-align:top\">Date Received: {{iar.date}}<p style=\"margin-top:10px\"><span class=\"fx-chk is-on\"></span> Complete<br><span class=\"fx-chk\"></span> Partial (pls. specify quantity)</p><div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{entity.treasurer}}</div><div class=\"sg-cap\">Supply and/or Property Custodian</div></div></td></tr></tbody></table>', 'A4', 'portrait', '0', 'entity.name,iar.no', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"blank_rows\":3}', NULL, '1', '1', @o + 40);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('requisition_issue_slip', 'Requisition and issue slip (RIS)', 'proforma', 'delivery', 'ris', 'Requisition and issue slip of the barangay: requisition, issuance, and the four signatures.', '<table class=\"fx\" style=\"width:100%\"><tbody><tr><td colspan=\"6\" class=\"fx-title\" style=\"text-align:center;padding:12px\">REQUISITION AND ISSUE SLIP</td></tr><tr><td style=\"width:12%\">Barangay:<br>Tel No.:</td><td style=\"width:24%\"><b>{{entity.short_upper}}</b><br>{{entity.phone}}</td><td style=\"width:20%\">City/Municipality:<br>Province:</td><td style=\"width:20%\">{{entity.city}}<br>{{entity.province}}</td><td style=\"width:9%\">RIS No.<br>Date:</td><td>{{ris.no}}<br>{{ris.date}}</td></tr><tr><td colspan=\"6\" class=\"fx-slot\">{{ris.items}}</td></tr><tr><td colspan=\"6\"><b>Purpose : {{project.purpose}}</b></td></tr><tr><td colspan=\"6\" style=\"padding:0\"><table class=\"fx fx-inner\" style=\"width:100%\"><tbody><tr><td style=\"width:15%;vertical-align:bottom;line-height:1.9\">Signature<br>Printed Name<br>Designation<br>Date</td><td style=\"vertical-align:top;height:110px\">Requested by:<div style=\"margin-top:34px;border-bottom:1px solid #000;width:80%;margin-left:auto;margin-right:auto\"></div><div style=\"text-align:center;font-weight:bold;text-decoration:underline\">{{project.requestor}}</div><div style=\"text-align:center\">Requisitioner</div></td><td style=\"vertical-align:top;height:110px\">Approved for Issuance:<div style=\"margin-top:34px;border-bottom:1px solid #000;width:80%;margin-left:auto;margin-right:auto\"></div><div style=\"text-align:center;font-weight:bold;text-decoration:underline\">{{entity.head_name}}</div><div style=\"text-align:center\">Punong Barangay</div></td><td style=\"vertical-align:top;height:110px\">Received by:<div style=\"margin-top:34px;border-bottom:1px solid #000;width:80%;margin-left:auto;margin-right:auto\"></div><div style=\"text-align:center;font-weight:bold;text-decoration:underline\">{{project.requestor}}</div><div style=\"text-align:center\">Requisitioner</div></td><td style=\"vertical-align:top;height:110px\">Issued by:<div style=\"margin-top:34px;border-bottom:1px solid #000;width:80%;margin-left:auto;margin-right:auto\"></div><div style=\"text-align:center;font-weight:bold;text-decoration:underline\">{{entity.treasurer}}</div><div style=\"text-align:center\">Barangay Treasurer</div></td></tr></tbody></table></td></tr></tbody></table>', 'A4', 'portrait', '0', 'entity.name,ris.no', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"blank_rows\":4}', NULL, '1', '1', @o + 50);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('request_for_quotation', 'Request for quotation (canvass form)', 'proforma', 'bid', 'canvass', 'The canvass form given to each supplier: the barangay\'s letterhead with its seals, the conditions, the items with blank prices for the supplier to fill in and sign.', '{{lgu.header}}<div class=\"fx-title\" style=\"text-align:center;margin:10px 0 6px\">REQUEST FOR QUOTATION</div><table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:52%\"></td><td>DATE: {{rfq.date}}<br>Quotation / PR No. {{pr.no}}</td></tr></tbody></table><table class=\"fx-lines\" style=\"width:72%;margin-top:8px\"><tbody><tr><td class=\"lbl-l\">Name of Company:</td><td class=\"val\"></td></tr><tr><td class=\"lbl-l\">Address:</td><td class=\"val\"></td></tr><tr><td class=\"lbl-l\">PhilGEPS No.:</td><td class=\"val\"></td></tr><tr><td class=\"lbl-l\">Project Title:</td><td class=\"val\">{{project.title}}</td></tr><tr><td class=\"lbl-l\">Approved Budget of the Contract:</td><td class=\"val\">PHP {{project.abc_plain}}</td></tr><tr><td class=\"lbl-l\">End-User/ Implementing Office:</td><td><b><u>{{entity.name_upper}}</u></b></td></tr></tbody></table><p style=\"margin-top:12px\"><b>Sir/Madam:</b></p><p>Please quote your lowest price quotation including government taxes on the item/s listed below and submit your quotation duly signed by you or your authorized representative not later than ______________ in an opened envelope.</p><table class=\"fx-plain\" style=\"width:100%\" data-section=\"notes\" title=\"Notes to the supplier\"><tbody><tr><td style=\"width:12%;vertical-align:top\">Note:</td><td>1. All entries must be typewritten<br>2. Delivery period must be within immediate calendar days<br>3. Warranty shall be for a period of three (3) months for supplies, one (1) year for equipment after acceptable by the {{entity.name_upper}} of the delivered goods.<br>4. Price validity shall be for the period of <u>120</u> calendar days.<br>5. Supplier/Contractor shall submit original brochures (if applicable)</td></tr></tbody></table><table class=\"fx-plain\" style=\"width:100%;margin-top:8px\"><tbody><tr><td style=\"width:60%\"></td><td><div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{entity.bac_chair_upper}}</div><div class=\"sg-cap\">BAC Chairman</div></div></td></tr></tbody></table><p style=\"margin:10px 0 2px\">After having carefully read and accepted the General Conditions, I/we submit our quotation/s for the item/s as follows:</p>{{rfq.items}}<table class=\"fx-lines\" style=\"width:100%;margin-top:8px\"><tbody><tr><td class=\"lbl-l\" style=\"width:18%\">Amount in Words:</td><td class=\"val\" colspan=\"3\"></td></tr><tr><td class=\"lbl-l\">Delivery Period:</td><td class=\"val\" style=\"width:32%\">{{rfq.delivery_period}}</td><td class=\"lbl-l\" style=\"width:12%\">Warranty:</td><td class=\"val\"></td></tr><tr><td class=\"lbl-l\">Price Validity:</td><td class=\"val\" colspan=\"3\"></td></tr></tbody></table><table class=\"fx-plain\" style=\"width:100%;margin-top:22px\"><tbody><tr><td style=\"width:58%\"></td><td><div style=\"border-top:1px solid #000;text-align:center\">Signature over Printed Name</div>Contact No:<br>Date:</td></tr></tbody></table>', 'A4', 'portrait', '0', 'entity.name', '0', 'layout', '{\"margin_top\":8,\"margin_right\":12,\"margin_bottom\":8,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9,\"table_size\":8.5,\"title_size\":13,\"blank_rows\":1}', NULL, '1', '1', @o + 60);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('abstract_of_canvass', 'Abstract of bids as quoted (abstract of canvass)', 'proforma', 'bid', 'abstract', 'The quotations of the suppliers canvassed side by side (total, validity, brand, remarks), signed by the BAC and approved by the Punong Barangay.', '<table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:58%\"></td><td>P.R No. : {{pr.no}}<br>Name of Project: {{project.title}}<br>Location of the Project: {{entity.location}}</td></tr></tbody></table><div class=\"fx-title\" style=\"text-align:center;margin:18px 0 4px;text-decoration:underline\">ABSTRACT OF BIDS AS QUOTED</div><p style=\"text-align:right\">( {{abstract.date}} )</p><p><b>Project Name: {{project.title}}<br>Project Location: {{entity.name}}, {{entity.city}}<br>Implementing Office: {{project.end_user}}</b></p><p style=\"margin:12px 0 2px\"><b>Approved Budget for the Contract: {{project.abc}}</b></p>{{abstract.table}}<div style=\"margin-top:34px\">{{entity.bac_signatures}}</div><p style=\"margin-top:20px\">Approved by:</p><div class=\"fx-sig\" style=\"text-align:left\"><div class=\"sg-name\">{{entity.head_name_upper}}</div><div class=\"sg-cap\">PUNONG BARANGAY</div></div>', 'A4', 'portrait', '0', 'entity.name,project.title', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":10,\"table_size\":9,\"title_size\":13}', NULL, '1', '1', @o + 70);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('disbursement_voucher', 'Disbursement voucher (DV)', 'proforma', 'billing', 'dv', 'Disbursement voucher of the barangay for the payment to the company: particulars, taxes withheld, net amount in words, supporting papers, boxes A to E.', '<table class=\"fx\" style=\"width:100%\"><tbody><tr><td colspan=\"2\" class=\"fx-title\" style=\"text-align:center;padding:10px\">DISBURSEMENT VOUCHER</td><td style=\"width:22%;vertical-align:bottom\">DV No. {{dv.no}}</td></tr><tr><td style=\"width:46%\">Barangay: <b>{{entity.short}}</b></td><td>City/Municipality: {{entity.city}}</td><td>Date: {{dv.date}}</td></tr><tr><td>Payee: <b>{{company.name}}</b></td><td>Province: {{entity.province}}</td><td>Fund: {{dv.fund}}</td></tr><tr><td>Address: {{company.address}}</td><td>TIN: {{company.tin}}</td><td></td></tr><tr><td colspan=\"3\" style=\"text-align:center;font-weight:bold\">PARTICULARS</td></tr><tr><td colspan=\"3\" style=\"padding:10px 14px\"><table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:70%\">To Withdraw Payment for the <b>{{dv.particulars}}</b><br>per attached supporting documents in the amount of ------------</td><td style=\"text-align:right;font-size:12pt;font-weight:bold;vertical-align:bottom\">{{dv.gross}}</td></tr><tr data-section=\"taxes\" title=\"Taxes withheld\"><td style=\"padding-top:16px\">{{dv.taxes}}</td><td style=\"text-align:right;font-size:12pt;font-weight:bold;vertical-align:bottom\">{{dv.net}}</td></tr><tr><td colspan=\"2\" style=\"padding:18px 0 0 18px\">Amount in words:<br><b>{{dv.net_words_upper}}</b></td></tr><tr data-section=\"papers\" title=\"Supporting papers attached\"><td colspan=\"2\" style=\"padding:18px 0 0 18px\">Supporting Papers Attached:{{dv.papers}}</td></tr><tr><td></td><td style=\"text-align:right;font-size:12pt\"><b>TOTAL:   {{dv.net}}</b></td></tr></tbody></table></td></tr><tr><td colspan=\"3\" style=\"padding:0\"><table class=\"fx fx-inner\" style=\"width:100%\"><tbody><tr><td style=\"width:34%;vertical-align:top\"><span class=\"fx-tag\">A</span> <b>Certified:</b><br>Existence of available appropriations for the charges/expenses indicated above<div style=\"margin-top:26px\">Signature:<br>Printed Name: <b><u>{{entity.appropriations_chair_upper}}</u></b><br>Position: Chairman, Committee on Appropriations<br><b>Date:</b></div></td><td style=\"width:33%;vertical-align:top\"><span class=\"fx-tag\">B</span> <b>Certified:</b><br>Funds (Cash) Available:<br><br><div style=\"margin-top:26px\">Signature:<br>Printed Name: <b><u>{{entity.treasurer_upper}}</u></b><br>Position: Barangay Treasurer<br><b>Date:</b></div></td><td style=\"vertical-align:top\"><span class=\"fx-tag\">C</span> <b>Certified:</b><br>As to validity, propriety, and legality of claim<br>Approved: FOR PAYMENT<div style=\"margin-top:26px\">Signature:<br>Printed Name: <b><u>{{entity.head_name_upper}}</u></b><br>Position: Barangay Captain<br><b>Date:</b></div></td></tr></tbody></table></td></tr><tr><td colspan=\"3\" style=\"vertical-align:top;height:110px\"><span class=\"fx-tag\">D</span> <b>Received Payment:</b><table class=\"fx-plain\" style=\"width:100%;margin-top:16px\"><tbody><tr><td style=\"width:50%;padding-left:40px\"><b><u>{{company.name_upper}}</u></b><br>Signature Over Printed Name</td><td>Check No. <u>{{dv.check_no}}</u><br>Bank Name: <u>{{dv.bank}}</u><br>OR Number: <u>{{dv.or_no}}</u></td><td style=\"vertical-align:middle\">Date: __________</td></tr><tr><td style=\"padding-top:10px\">Date: __________</td><td></td><td></td></tr></tbody></table></td></tr><tr><td colspan=\"3\" style=\"padding:0\" data-section=\"entries\" title=\"E. Accounting entries\"><table class=\"fx fx-inner\" style=\"width:100%\"><tbody><tr><td colspan=\"4\"><b>E. Accounting Entries:</b></td></tr><tr><th style=\"width:36%\">Account</th><th style=\"width:22%\">Account Code</th><th style=\"width:21%\">Debit</th><th>Credit</th></tr><tr><td> </td><td></td><td></td><td></td></tr><tr><td> </td><td></td><td></td><td></td></tr><tr><td> </td><td></td><td></td><td></td></tr><tr><td> </td><td></td><td></td><td></td></tr><tr><td style=\"vertical-align:top;height:150px\"></td><td colspan=\"3\" style=\"vertical-align:top\">Prepared By:<table class=\"fx-plain\" style=\"width:100%;margin-top:26px\"><tbody><tr><td style=\"width:62%;text-align:center\"><div style=\"border-top:1px solid #000;width:70%;margin:0 auto\"></div>{{entity.bookkeeper}}<br>Barangay Bookkeeper</td><td style=\"text-align:center\"><div style=\"border-top:1px solid #000;width:70%;margin:0 auto\"></div>Date</td></tr></tbody></table><div style=\"margin-top:12px\">Approved By:</div><table class=\"fx-plain\" style=\"width:100%;margin-top:22px\"><tbody><tr><td style=\"width:62%;text-align:center\"><div style=\"border-top:1px solid #000;width:70%;margin:0 auto\"></div>{{entity.city_accountant}}<br>City/Municipal Accountant</td><td style=\"text-align:center\"><div style=\"border-top:1px solid #000;width:70%;margin:0 auto\"></div>Date</td></tr></tbody></table></td></tr></tbody></table></td></tr></tbody></table>', 'A4', 'portrait', '0', 'entity.name,dv.gross', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9,\"table_size\":8.5,\"title_size\":13}', NULL, '1', '1', @o + 80);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('document_transmittal', 'Transmittal of documents (SOP)', 'letter', 'billing', 'transmittal', 'Transmittal of the papers released to the barangay (delivered by the sales representative or picked up at the office); the signed copy must come back.', '<table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:70px;vertical-align:top\" data-section=\"logo\" title=\"Company logo\">{{company.logo}}</td><td style=\"vertical-align:top\"><div style=\"font-size:14pt;font-weight:bold\">{{company.name}}</div><div>{{company.address}}</div><div>TIN {{company.tin}}   Tel. {{company.phone}}   {{company.email}}</div></td></tr></tbody></table><hr><div class=\"fx-title\" style=\"text-align:center;margin:6px 0 10px\">TRANSMITTAL</div><table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:60%\">To: <b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</td><td style=\"vertical-align:top\">Transmittal No.: <b>{{transmittal.no}}</b><br>Date: {{transmittal.date}}<br>Transaction: {{project.txn_form_no}}<br>P.O. No.: {{po.no}}</td></tr></tbody></table><p style=\"margin-top:12px\">We are transmitting herewith the following documents for <b>{{project.title}}</b>:</p>{{sop.papers_table}}<p>Kindly acknowledge receipt by signing below and returning a copy of this transmittal.</p><table class=\"fx-plain\" style=\"width:100%;margin-top:18px\"><tbody><tr><td style=\"width:50%;vertical-align:top\">Released by:<div class=\"fx-sig\" style=\"text-align:left\"><div class=\"sg-name\">{{transmittal.released_by}}</div><div class=\"sg-cap\">{{company.name}}</div></div></td><td style=\"vertical-align:top\">Received by:<div class=\"fx-sig\" style=\"text-align:left\"><div class=\"sg-name\"> </div><div class=\"sg-cap\">Signature over Printed Name / Date</div></div></td></tr></tbody></table>', 'A4', 'portrait', '0', 'entity.name,transmittal.no', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13}', NULL, '1', '1', @o + 90);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('bidding_form', 'Bidding form (details of the bidding)', 'internal', 'internal', 'bidding_form', 'The details of a bidding given by the sales representative: project, budget, schedule, specifications and submission requirements.', '<table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:70px;vertical-align:top\" data-section=\"logo\" title=\"Company logo\">{{company.logo}}</td><td style=\"vertical-align:top\"><div style=\"font-size:14pt;font-weight:bold\">{{company.name}}</div><div>{{company.address}}</div><div>TIN {{company.tin}}   Tel. {{company.phone}}   {{company.email}}</div></td></tr></tbody></table><hr><div class=\"fx-title\" style=\"text-align:center;margin:6px 0 10px\">BIDDING FORM</div><table class=\"fx\" style=\"width:100%\"><tbody><tr><td style=\"width:32%\">Series / project no.</td><td>{{project.no}}   {{project.txn_form_no}}</td></tr><tr><td>Procuring entity</td><td><b>{{entity.name}}</b>, {{entity.city}}, {{entity.province}}</td></tr><tr><td>Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Pre-bid conference</td><td>{{project.prebid}}</td></tr><tr><td>Bid deadline / opening</td><td>{{project.bid_deadline}}</td></tr><tr><td>Requestor / end-user</td><td>{{project.requestor}} {{project.end_user}}</td></tr><tr><td>Inspector</td><td>{{project.inspector}}</td></tr><tr><td>Submission requirements</td><td>{{entity.requirement_notes}}</td></tr><tr><td>Specifications</td><td>{{project.specs}}</td></tr><tr><td>Sales representative</td><td>{{project.sales_rep}}</td></tr></tbody></table>{{lines.table}}', 'A4', 'portrait', '0', 'project.title,entity.name', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13}', NULL, '1', '1', @o + 100);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('invitation_to_bid', 'Invitation to bid (ITB)', 'proforma', 'bid', 'itb', 'Invitation to bid in the name of the Bids and Awards Committee of the barangay.', '{{lgu.header}}<div class=\"fx-title\" style=\"text-align:center;margin:12px 0\">INVITATION TO BID</div><p style=\"text-align:center\"><b>{{project.title}}</b><br>{{project.reference_no}}</p><ol><li>The {{entity.name}}, through its approved budget, intends to apply the sum of <b>{{project.abc_words}} ({{project.abc}})</b> being the Approved Budget for the Contract (ABC) to payments under the contract for {{project.title}}. Bids received in excess of the ABC shall be automatically rejected at bid opening.</li><li>The {{entity.name}} now invites bids for the above procurement project. Delivery of the goods is required within {{project.delivery_days}}. Bidders should have completed a contract similar to the project.</li><li>Bidding will be conducted through open competitive bidding procedures using a non-discretionary \"pass/fail\" criterion as specified in the applicable procurement law and its implementing rules.</li><li>A pre-bid conference shall be held on {{project.prebid}} at {{entity.address}}.</li><li>Bids must be duly received by the BAC Secretariat at {{entity.address}} on or before {{project.bid_deadline}}. Late bids shall not be accepted.</li><li>The {{entity.name}} reserves the right to reject any and all bids, declare a failure of bidding, or not award the contract at any time prior to contract award, without thereby incurring any liability to the affected bidder or bidders.</li></ol><table class=\"fx-plain\" style=\"width:100%;margin-top:24px\"><tbody><tr><td style=\"width:55%\"></td><td><div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{entity.bac_chair_upper}}</div><div class=\"sg-cap\">BAC Chairman</div></div></td></tr></tbody></table>', 'A4', 'portrait', '0', 'entity.name,project.title,project.abc', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13}', NULL, '1', '1', @o + 110);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('letter_to_coa', 'Letter to COA', 'letter', 'bid', 'coa_letter', 'Letter of the BAC informing the COA auditor of the bidding schedule and inviting a representative as observer.', '{{lgu.header}}<p style=\"text-align:right\">{{date.today}}</p><p><b>The Audit Team Leader</b><br>Commission on Audit<br>{{entity.city}}, {{entity.province}}</p><p><b>Subject: Invitation to observe the bidding for {{project.title}}</b></p><p>Sir/Madam:</p><p>The Bids and Awards Committee of {{entity.name}} respectfully informs your office of the procurement of <b>{{project.title}}</b> ({{project.reference_no}}) with an Approved Budget for the Contract of {{project.abc}}.</p><p>The pre-bid conference is scheduled on {{project.prebid}} and the opening of bids on {{project.bid_deadline}}, at {{entity.address}}. We would be glad to have a representative of your office attend as observer.</p><p>Thank you.</p><p style=\"margin-top:26px\">Very truly yours,</p><div class=\"fx-sig\" style=\"text-align:left\"><div class=\"sg-name\">{{entity.bac_chair_upper}}</div><div class=\"sg-cap\">BAC Chairman</div></div>', 'A4', 'portrait', '0', 'entity.name,project.title', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13}', NULL, '1', '1', @o + 120);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('approved_budget_contract', 'Approved budget for the contract (ABC)', 'proforma', 'bid', 'abc', 'Certification of the approved budget for the contract, with its breakdown (asked by the Cebu City offices).', '{{lgu.header}}<div class=\"fx-title\" style=\"text-align:center;margin:12px 0\">APPROVED BUDGET FOR THE CONTRACT</div><table class=\"fx\" style=\"width:100%\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference</td><td>{{project.reference_no}}</td></tr><tr><td>Source of funds</td><td>{{project.funding_source}}</td></tr><tr><td>Approved budget</td><td><b>{{project.abc}}</b> ({{project.abc_words}})</td></tr></tbody></table>{{pr.items}}<p>This is to certify that the above amount is the approved budget for the contract of the project.</p><table class=\"fx-plain\" style=\"width:100%;margin-top:24px\"><tbody><tr><td style=\"width:50%\"><div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{entity.treasurer_upper}}</div><div class=\"sg-cap\">Barangay Treasurer</div></div></td><td><div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{entity.head_name_upper}}</div><div class=\"sg-cap\">Punong Barangay</div></div></td></tr></tbody></table>', 'A4', 'portrait', '0', 'entity.name,project.abc', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13}', NULL, '1', '1', @o + 130);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('special_power_of_attorney', 'Special power of attorney (SPA)', 'contract', 'bid', 'spa', 'Special power of attorney of the proprietor appointing the representative for the pre-bid conference and the bidding (for notarization).', '<div class=\"fx-title\" style=\"text-align:center;margin:6px 0 14px\">SPECIAL POWER OF ATTORNEY</div><p><b>KNOW ALL MEN BY THESE PRESENTS:</b></p><p>I, <b>{{signatory.name}}</b>, of legal age, Filipino, {{signatory.position}} of <b>{{company.name}}</b>, with business address at {{company.address}}, do hereby name, constitute and appoint <b>{{project.submitter}}</b>, of legal age, as my true and lawful attorney-in-fact, for me and in my name, place and stead, to do and perform the following acts:</p><ol><li>To attend the pre-bid conference and the opening of bids of <b>{{project.title}}</b> ({{project.reference_no}}) of the {{entity.name}};</li><li>To submit, sign and receive all documents relative to the said bidding, including the bid, clarifications and notices;</li><li>To do all acts necessary and incidental to the foregoing.</li></ol><p>HEREBY GIVING AND GRANTING unto my said attorney-in-fact full power and authority to do and perform the acts above, and hereby ratifying all that my said attorney-in-fact shall lawfully do by virtue hereof.</p><p>IN WITNESS WHEREOF, I have hereunto set my hand this ____ day of __________ at __________.</p><table class=\"fx-plain\" style=\"width:100%;margin-top:22px\"><tbody><tr><td style=\"width:50%\"><div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{signatory.name}}</div><div class=\"sg-cap\">Principal</div></div></td><td><div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{project.submitter}}</div><div class=\"sg-cap\">Attorney-in-fact</div></div></td></tr></tbody></table><p style=\"margin-top:22px\"><b>ACKNOWLEDGMENT</b></p><p>[Notarial acknowledgment]</p>', 'A4', 'portrait', '0', 'signatory.name,project.submitter', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13}', NULL, '1', '1', @o + 140);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('statement_ongoing_contracts', 'Statement of all ongoing government and private contracts', 'proforma', 'bid', 'slcc', 'Statement of ongoing contracts, including contracts awarded but not yet started.', '<table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:70px;vertical-align:top\" data-section=\"logo\" title=\"Company logo\">{{company.logo}}</td><td style=\"vertical-align:top\"><div style=\"font-size:14pt;font-weight:bold\">{{company.name}}</div><div>{{company.address}}</div><div>TIN {{company.tin}}   Tel. {{company.phone}}   {{company.email}}</div></td></tr></tbody></table><hr><div class=\"fx-title\" style=\"text-align:center;margin:6px 0 4px\">STATEMENT OF ALL ONGOING GOVERNMENT AND PRIVATE CONTRACTS</div><p style=\"text-align:center\">{{project.title}} ({{project.reference_no}})</p><p>Business name: <b>{{company.name}}</b>. Including contracts awarded but not yet started.</p><table class=\"fx\" style=\"width:100%\"><thead><tr><th>Name of the contract</th><th>Date of the contract</th><th>Contract duration</th><th>Owner\'s name and address</th><th>Kind of goods</th><th>Amount of contract</th><th>Value of outstanding contract / date of delivery</th></tr></thead><tbody><tr><td> </td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td> </td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td> </td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td> </td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td> </td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><div class=\"fx-sig\" style=\"text-align:left\"><div class=\"sg-name\">{{signatory.name}}</div><div class=\"sg-cap\">{{signatory.position}}<br>{{company.name}}</div></div><p>Date: {{date.today}}</p>', 'Legal', 'portrait', '0', 'company.name', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13}', NULL, '1', '1', @o + 150);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('statement_similar_contracts', 'Statement of similar completed contracts', 'proforma', 'bid', 'slcc', 'Statement of completed contracts similar to the project.', '<table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:70px;vertical-align:top\" data-section=\"logo\" title=\"Company logo\">{{company.logo}}</td><td style=\"vertical-align:top\"><div style=\"font-size:14pt;font-weight:bold\">{{company.name}}</div><div>{{company.address}}</div><div>TIN {{company.tin}}   Tel. {{company.phone}}   {{company.email}}</div></td></tr></tbody></table><hr><div class=\"fx-title\" style=\"text-align:center;margin:6px 0 4px\">STATEMENT OF SINGLE LARGEST COMPLETED CONTRACT SIMILAR TO THE CONTRACT TO BE BID</div><p style=\"text-align:center\">{{project.title}} ({{project.reference_no}})</p><p>Business name: <b>{{company.name}}</b>.</p><table class=\"fx\" style=\"width:100%\"><thead><tr><th>Name of the contract</th><th>Date of the contract</th><th>Contract duration</th><th>Owner\'s name and address</th><th>Kind of goods</th><th>Amount of contract</th><th>Value of outstanding contract / date of delivery</th></tr></thead><tbody><tr><td> </td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td> </td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td> </td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td> </td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td> </td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><div class=\"fx-sig\" style=\"text-align:left\"><div class=\"sg-name\">{{signatory.name}}</div><div class=\"sg-cap\">{{signatory.position}}<br>{{company.name}}</div></div><p>Date: {{date.today}}</p>', 'Legal', 'portrait', '0', 'company.name', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13}', NULL, '1', '1', @o + 160);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('letter_of_intent', 'Letter of intent', 'letter', 'bid', 'letter_intent', 'Letter of intent to participate in the bidding.', '<table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:70px;vertical-align:top\" data-section=\"logo\" title=\"Company logo\">{{company.logo}}</td><td style=\"vertical-align:top\"><div style=\"font-size:14pt;font-weight:bold\">{{company.name}}</div><div>{{company.address}}</div><div>TIN {{company.tin}}   Tel. {{company.phone}}   {{company.email}}</div></td></tr></tbody></table><hr><p style=\"text-align:right\">{{date.today}}</p><p><b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Subject: Letter of intent</b></p><p>Dear Sir/Madam:</p><p>We, <b>{{company.name}}</b>, signify our intention to participate in the bidding for <b>{{project.title}}</b> ({{project.reference_no}}) with an Approved Budget for the Contract of {{project.abc}}.</p><p>We have authorized <b>{{project.submitter}}</b> to represent us in the pre-bid conference and the bidding.</p><p style=\"margin-top:26px\">Very truly yours,</p><div class=\"fx-sig\" style=\"text-align:left\"><div class=\"sg-name\">{{signatory.name}}</div><div class=\"sg-cap\">{{signatory.position}}<br>{{company.name}}</div></div>', 'A4', 'portrait', '0', 'entity.name,project.title', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13}', NULL, '1', '1', @o + 170);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('production_details', 'Production details', 'proforma', 'bid', 'production', 'Where and how the goods are produced or sourced, and the capacity to deliver within the period.', '<table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:70px;vertical-align:top\" data-section=\"logo\" title=\"Company logo\">{{company.logo}}</td><td style=\"vertical-align:top\"><div style=\"font-size:14pt;font-weight:bold\">{{company.name}}</div><div>{{company.address}}</div><div>TIN {{company.tin}}   Tel. {{company.phone}}   {{company.email}}</div></td></tr></tbody></table><hr><div class=\"fx-title\" style=\"text-align:center;margin:6px 0 10px\">PRODUCTION DETAILS</div><p style=\"text-align:center\">{{project.title}}</p><table class=\"fx\" style=\"width:100%\"><tbody><tr><td style=\"width:32%\">Source / manufacturer of the goods</td><td> </td></tr><tr><td>Place of production / warehouse</td><td>{{company.address}}</td></tr><tr><td>Capacity</td><td> </td></tr><tr><td>Delivery period</td><td>{{project.delivery_days}}</td></tr><tr><td>Delivery site</td><td>{{project.delivery_site}}</td></tr></tbody></table>{{lines.table}}<div class=\"fx-sig\" style=\"text-align:left\"><div class=\"sg-name\">{{signatory.name}}</div><div class=\"sg-cap\">{{signatory.position}}</div></div>', 'A4', 'portrait', '0', 'company.name', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13}', NULL, '1', '1', @o + 180);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('manpower_schedule', 'Manpower schedule', 'proforma', 'bid', 'manpower', 'The people assigned to the project, their positions and their schedule.', '<table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:70px;vertical-align:top\" data-section=\"logo\" title=\"Company logo\">{{company.logo}}</td><td style=\"vertical-align:top\"><div style=\"font-size:14pt;font-weight:bold\">{{company.name}}</div><div>{{company.address}}</div><div>TIN {{company.tin}}   Tel. {{company.phone}}   {{company.email}}</div></td></tr></tbody></table><hr><div class=\"fx-title\" style=\"text-align:center;margin:6px 0 10px\">MANPOWER SCHEDULE</div><p style=\"text-align:center\">{{project.title}}</p><table class=\"fx\" style=\"width:100%\"><thead><tr><th style=\"width:6%\">No.</th><th>Name</th><th>Position / work</th><th>Schedule</th><th>Remarks</th></tr></thead><tbody><tr><td style=\"text-align:center\">1</td><td>{{project.pm}}</td><td>Project manager</td><td>{{project.start_date}} to {{project.due_date}}</td><td></td></tr><tr><td> </td><td></td><td></td><td></td><td></td></tr><tr><td> </td><td></td><td></td><td></td><td></td></tr><tr><td> </td><td></td><td></td><td></td><td></td></tr><tr><td> </td><td></td><td></td><td></td><td></td></tr><tr><td> </td><td></td><td></td><td></td><td></td></tr></tbody></table><div class=\"fx-sig\" style=\"text-align:left\"><div class=\"sg-name\">{{signatory.name}}</div><div class=\"sg-cap\">{{signatory.position}}</div></div>', 'A4', 'portrait', '0', 'company.name', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13}', NULL, '1', '1', @o + 190);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('warranty_certificate', 'Warranty certificate', 'proforma', 'bid', 'warranty_cert', 'Warranty of the company on the goods or the work.', '<table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:70px;vertical-align:top\" data-section=\"logo\" title=\"Company logo\">{{company.logo}}</td><td style=\"vertical-align:top\"><div style=\"font-size:14pt;font-weight:bold\">{{company.name}}</div><div>{{company.address}}</div><div>TIN {{company.tin}}   Tel. {{company.phone}}   {{company.email}}</div></td></tr></tbody></table><hr><div class=\"fx-title\" style=\"text-align:center;margin:10px 0 14px\">WARRANTY CERTIFICATE</div><p>This is to certify that <b>{{company.name}}</b> warrants the goods / work delivered to the <b>{{entity.name}}</b> under <b>{{project.title}}</b> ({{project.contract_ref}}) against defects in materials and workmanship for a period of <b>{{project.warranty_months}}</b> from the date of acceptance (three (3) months for supplies, one (1) year for equipment, unless the contract states otherwise).</p><p>Any item found defective within the warranty period shall be repaired or replaced at no cost to the {{entity.name}} within seven (7) calendar days from notice.</p><p>Issued this {{date.today}}.</p><div class=\"fx-sig\" style=\"text-align:left\"><div class=\"sg-name\">{{signatory.name}}</div><div class=\"sg-cap\">{{signatory.position}}<br>{{company.name}}</div></div>', 'A4', 'portrait', '0', 'company.name,entity.name', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13}', NULL, '1', '1', @o + 200);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('bac_resolution', 'BAC resolution recommending the award', 'proforma', 'award', 'bac_resolution', 'Resolution of the Bids and Awards Committee recommending the award to the company (prepared for the BAC\'s signatures).', '{{lgu.header}}<div class=\"fx-title\" style=\"text-align:center;margin:12px 0 4px\">BAC RESOLUTION NO. ______</div><p style=\"text-align:center\"><b>RECOMMENDING THE AWARD OF {{project.title_upper}} TO {{company.name_upper}}</b></p><p>WHEREAS, the {{entity.name}} conducted the procurement of {{project.title}} ({{project.reference_no}}) with an Approved Budget for the Contract of {{project.abc}};</p><p>WHEREAS, after evaluation, the bid of <b>{{company.name}}</b> in the amount of <b>{{project.bid_amount}}</b> ({{project.bid_amount_words}}) was found to be the lowest calculated and responsive bid and passed the post-qualification;</p><p>NOW, THEREFORE, WE, the members of the Bids and Awards Committee, RESOLVE, as it is hereby resolved, to recommend to the Punong Barangay the award of the contract to <b>{{company.name}}</b>.</p><p>RESOLVED this ____ day of __________ at {{entity.name}}, {{entity.city}}.</p><div style=\"margin-top:24px\">{{entity.bac_signatures}}</div><p style=\"margin-top:18px\">Approved by:</p><div class=\"fx-sig\" style=\"text-align:left\"><div class=\"sg-name\">{{entity.head_name_upper}}</div><div class=\"sg-cap\">Punong Barangay</div></div>', 'A4', 'portrait', '0', 'entity.name,project.title', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13}', NULL, '1', '1', @o + 210);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('notice_of_award', 'Notice of award (NOA)', 'proforma', 'award', 'noa', 'Notice of award to the company, for the Punong Barangay\'s signature and the company\'s conforme.', '{{lgu.header}}<p style=\"text-align:right\">{{date.today}}</p><p><b>{{company.name_upper}}</b><br>{{company.address}}</p><div class=\"fx-title\" style=\"text-align:center;margin:10px 0\">NOTICE OF AWARD</div><p>Dear Sir/Madam:</p><p>We are happy to notify you that your bid dated __________ for <b>{{project.title}}</b> ({{project.reference_no}}) in the amount of <b>{{project.bid_amount}}</b> ({{project.bid_amount_words}}) is hereby accepted.</p><p>You are required to furnish the performance security, if required, and to enter into contract with us within the period set by the procurement rules. Failure to do so shall constitute sufficient ground for the cancellation of the award.</p><p style=\"margin-top:22px\">Very truly yours,</p><div class=\"fx-sig\" style=\"text-align:left\"><div class=\"sg-name\">{{entity.head_name_upper}}</div><div class=\"sg-cap\">Punong Barangay</div></div><p style=\"margin-top:22px\">Conforme:</p><div class=\"fx-sig\" style=\"text-align:left\"><div class=\"sg-name\">{{signatory.name}}</div><div class=\"sg-cap\">{{signatory.position}}, {{company.name}}<br>Date: __________</div></div>', 'A4', 'portrait', '0', 'entity.name,project.title,project.bid_amount', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13}', NULL, '1', '1', @o + 220);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('notice_to_proceed', 'Notice to proceed (NTP)', 'proforma', 'award', 'ntp', 'Notice to proceed, for the Punong Barangay\'s signature and the company\'s conforme.', '{{lgu.header}}<p style=\"text-align:right\">{{date.today}}</p><p><b>{{company.name_upper}}</b><br>{{company.address}}</p><div class=\"fx-title\" style=\"text-align:center;margin:10px 0\">NOTICE TO PROCEED</div><p>Dear Sir/Madam:</p><p>The attached contract / purchase order {{project.contract_ref}} for <b>{{project.title}}</b> in the amount of <b>{{project.contract_amount}}</b> having been approved, notice is hereby given that you may now proceed with the delivery / implementation in accordance with its terms and conditions.</p><p>The delivery / completion shall be within {{project.delivery_days}} from your receipt of this notice.</p><p style=\"margin-top:22px\">Very truly yours,</p><div class=\"fx-sig\" style=\"text-align:left\"><div class=\"sg-name\">{{entity.head_name_upper}}</div><div class=\"sg-cap\">Punong Barangay</div></div><p style=\"margin-top:22px\">Conforme:</p><div class=\"fx-sig\" style=\"text-align:left\"><div class=\"sg-name\">{{signatory.name}}</div><div class=\"sg-cap\">{{signatory.position}}, {{company.name}}<br>Date: __________</div></div>', 'A4', 'portrait', '0', 'entity.name,project.title', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13}', NULL, '1', '1', @o + 230);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('certificate_of_completion', 'Certificate of completion', 'proforma', 'closeout', 'completion_cert', 'Certificate of completion signed by the inspector and the Barangay Captain.', '{{lgu.header}}<div class=\"fx-title\" style=\"text-align:center;margin:16px 0\">CERTIFICATE OF COMPLETION</div><p>This is to certify that <b>{{company.name}}</b> has satisfactorily completed / delivered <b>{{project.title}}</b> under {{project.contract_ref}} for the <b>{{entity.name}}</b> in accordance with the specifications, in the amount of <b>{{project.contract_amount}}</b>.</p><p>Date of completion: <b>{{project.completion_date}}</b></p><p>Issued this ____ day of __________ for whatever legal purpose it may serve.</p><table class=\"fx-plain\" style=\"width:100%;margin-top:30px\"><tbody><tr><td style=\"width:50%\">Inspected by:<div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{project.inspector_upper}}</div><div class=\"sg-cap\">Inspector</div></div></td><td>Approved by:<div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{entity.head_name_upper}}</div><div class=\"sg-cap\">Barangay Captain</div></div></td></tr></tbody></table>', 'A4', 'portrait', '0', 'entity.name,project.title', '0', 'layout', '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13}', NULL, '1', '1', @o + 240);

INSERT INTO brgy_template_versions (template_id, version_no, name, body, layout_json, positions_json, change_note)
SELECT t.id, t.version_no, t.name, t.body, t.layout_json, t.positions_json, 'Supplied with the program' FROM brgy_templates t
 WHERE t.code IN ('txn_form','purchase_request','purchase_order','inspection_acceptance_report','requisition_issue_slip','request_for_quotation','abstract_of_canvass','disbursement_voucher','document_transmittal','bidding_form','invitation_to_bid','letter_to_coa','approved_budget_contract','special_power_of_attorney','statement_ongoing_contracts','statement_similar_contracts','letter_of_intent','production_details','manpower_schedule','warranty_certificate','bac_resolution','notice_of_award','notice_to_proceed','certificate_of_completion') AND NOT EXISTS (SELECT 1 FROM brgy_template_versions v WHERE v.template_id = t.id);

-- ---------------------------------------------------------------------
--  7. Record the change in the audit trail
-- ---------------------------------------------------------------------
INSERT INTO audit_trail (username, user_roles, ip_address, workstation, module, page_key, action, record_type, record_ref, reason)
VALUES ('system', 'Database migration', '127.0.0.1', 'SQL migration', 'admin', 'admin.page_access', 'access_change', 'page',
        'SOP Steps & Papers, Transaction Monitoring (SOP)',
        'Migration 2026_11_03: the SOP of the company (small value procurement, bidding, payment), signed copies of the papers, configurable forms (format, pre-printed paper)');

-- Done. Next steps in the application:
--   Barangay Contracts > Contracting Settings > The SOP: the tradename, the small value limit, the types of transaction.
--   Barangays & Procuring Entities: upload the seals (barangay and city / municipality); add the Chairman of the
--     Committee on Appropriations, the bookkeeper and the city / municipal accountant to the officials; tick
--     "Asks for the ABC and the Aboitiz requirements" for the offices that do (e.g. Cebu City).
--   Proforma & Form Templates: open a template > Format to set paper, margins, font, columns and copies, or
--     > Pre-printed paper to place the values on the barangay's own pads (test print with a millimetre grid).
--   Projects & Contracts > New transaction: choose the process; the Process tab takes it step by step.
